// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool _wasFraud, address caller) public {
        // No precondition needed; the reference always satisfies the rule.
        vm.prank(caller);
        bool ret = c.logStartedLiquidation(_wasFraud);
        assertTrue(ret == c.approvedToLog(caller));
    }
}

